import React, { useEffect, useState } from "react";

import { DeliveryCategoryTag } from "./DeliveryShared";

const OFFER_SECONDS = 30;

export default function DeliveryCourierOffer({ delivery, onAccept, onDecline, onTimeout, busy = false }) {
  const [secondsLeft, setSecondsLeft] = useState(delivery?.offer_expires_in || OFFER_SECONDS);

  useEffect(() => {
    setSecondsLeft(delivery?.offer_expires_in || OFFER_SECONDS);
    const timer = window.setInterval(() => {
      setSecondsLeft((value) => {
        if (value <= 1) {
          window.clearInterval(timer);
          onTimeout?.();
          return 0;
        }
        return value - 1;
      });
    }, 1000);
    return () => window.clearInterval(timer);
  }, [delivery?.id, onTimeout]);

  if (!delivery) return null;

  return (
    <div className="delivery-uber-offer" role="dialog" aria-label="New delivery request">
      <div className="delivery-uber-offer__card">
        <div className="delivery-uber-offer__header">
          <div>
            <p className="delivery-uber-offer__eyebrow">New delivery request</p>
            <div className="delivery-uber-offer__fare">{delivery.fare} MRU</div>
          </div>
          <div className="delivery-uber-offer__timer">{secondsLeft}s</div>
        </div>

        <p className="delivery-uber-offer__meta">
          {delivery.distance_km} km · ~{delivery.estimated_duration_minutes || 30} min
        </p>

        <div className="delivery-uber-offer__route">
          <div className="delivery-uber-offer__route-row">
            <span className="delivery-uber__location-dot delivery-uber__location-dot--pickup" />
            <div>
              <small>Pickup</small>
              <strong>{delivery.pickup}</strong>
            </div>
          </div>
          <div className="delivery-uber-offer__route-row">
            <span className="delivery-uber__location-dot delivery-uber__location-dot--dropoff" />
            <div>
              <small>Drop-off</small>
              <strong>{delivery.destination}</strong>
            </div>
          </div>
        </div>

        <div className="delivery-uber-offer__tags">
          <DeliveryCategoryTag category={delivery.service_category} />
          <span className="delivery-dash__offer-package">
            📦 {delivery.package_type || "small"} package
          </span>
          {delivery.is_urgent ? <span className="delivery-uber__tag">Urgent</span> : null}
          {delivery.is_fragile ? <span className="delivery-uber__tag">Fragile</span> : null}
        </div>

        <div className="delivery-uber-offer__actions">
          <button type="button" className="delivery-uber__btn delivery-uber__btn--secondary" onClick={onDecline}>
            Decline
          </button>
          <button type="button" className="delivery-uber__btn" disabled={busy} onClick={() => onAccept(delivery)}>
            {busy ? "Accepting..." : `Accept · ${delivery.fare} MRU`}
          </button>
        </div>
      </div>
    </div>
  );
}
