import React, { useState } from "react";

export default function DeliveryPickupProof({
  delivery,
  busy = false,
  onSubmit,
}) {
  const [pickupPin, setPickupPin] = useState("");
  const requiresVerification = Boolean(delivery?.requires_pickup_verification);

  if (!requiresVerification) {
    return (
      <button type="button" className="delivery-uber-trip__action-btn delivery-uber-trip__action-btn--primary" disabled={busy} onClick={() => onSubmit({ pickupConfirmed: true })}>
        {busy ? "Updating..." : "Picked up package"}
      </button>
    );
  }

  return (
    <div className="delivery-uber-trip__pickup-proof">
      <p className="delivery-uber-trip__subtitle">
        Ask the customer for the 4-digit pickup confirmation code.
      </p>
      <label className="delivery-uber__input-card">
        <span className="delivery-uber__input-label">Pickup PIN</span>
        <input
          value={pickupPin}
          onChange={(e) => setPickupPin(e.target.value.replace(/\D/g, "").slice(0, 4))}
          placeholder="4-digit PIN"
          inputMode="numeric"
        />
      </label>
      <button
        type="button"
        className="delivery-uber-trip__action-btn delivery-uber-trip__action-btn--primary"
        disabled={busy || pickupPin.length !== 4}
        onClick={() => onSubmit({ pickupPin })}
      >
        {busy ? "Verifying..." : "Verify PIN & pick up"}
      </button>
    </div>
  );
}
